                       .append(reservationId).append(",")
                       .append(Formatter.formatDateIso(checkIn)).append(",")
                       .append(Formatter.formatDateIso(checkOut)).append("\n");
                    occupiedCount++;
                }
            }
        }

        csv.append("total,").append(occupiedCount).append("/").append(allRooms.size());

        return csv.toString();
