    public String generateRevenueReport(YearMonth yearMonth, Connection conn) throws SQLException {
        StringBuilder csv = new StringBuilder();
        csv.append("reservation,room,check_in,check_out,status,amount\n");

        BigDecimal total = BigDecimal.ZERO;

        try (var stmt = conn.prepareStatement(
            "SELECT id, room_number, check_in, check_out, status, amount_paid, refund " +
            "FROM reservations " +
            "WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ? " +
            "AND status IN (?, ?, ?) " +
            "ORDER BY check_in, id")) {

            stmt.setInt(1, yearMonth.getYear());
            stmt.setInt(2, yearMonth.getMonthValue());
            stmt.setString(3, ReservationStatus.CONFIRMED.toString());
            stmt.setString(4, ReservationStatus.CHECKED_IN.toString());
            stmt.setString(5, ReservationStatus.CHECKED_OUT.toString());

            ResultSet rs = stmt.executeQuery();
            var rows = new ArrayList<>();
            while (rs.next()) {
                var row = new Object[] {
                    rs.getLong("id"),
                    rs.getInt("room_number"),
                    rs.getDate("check_in").toLocalDate(),
                    rs.getDate("check_out").toLocalDate(),
                    rs.getString("status"),
                    rs.getBigDecimal("amount_paid"),
                    rs.getBigDecimal("refund")
                };
                rows.add(row);
            }

            for (var row : rows) {
                long reservationId = (Long) row[0];
                int roomNumber = (Integer) row[1];
                LocalDate checkIn = (LocalDate) row[2];
                LocalDate checkOut = (LocalDate) row[3];
                String status = (String) row[4];
                BigDecimal amountPaid = (BigDecimal) row[5];
                BigDecimal refund = (BigDecimal) row[6];

                BigDecimal amount = amountPaid;
                if (refund != null && refund.compareTo(BigDecimal.ZERO) > 0) {
                    amount = amountPaid.subtract(refund);
                }

                csv.append(reservationId).append(",")
                   .append(roomNumber).append(",")
                   .append(Formatter.formatDateIso(checkIn)).append(",")
                   .append(Formatter.formatDateIso(checkOut)).append(",")
                   .append(status).append(",")
                   .append(Formatter.formatCurrencyForCsv(amount)).append("\n");

                total = total.add(amount);
            }
        }

        csv.append("total,,,,").append(Formatter.formatCurrencyForCsv(total));

        return csv.toString();
    }
