            stmt.setInt(1, yearMonth.getYear());
            stmt.setInt(2, yearMonth.getMonthValue());
            stmt.setString(3, ReservationStatus.CONFIRMED.toString());
            stmt.setString(4, ReservationStatus.CHECKED_IN.toString());
            stmt.setString(5, ReservationStatus.CHECKED_OUT.toString());

            ResultSet rs = stmt.executeQuery();
            var rows = new ArrayList<>();
            while (rs.next()) {
                var row = new Object[] {
                    rs.getLong("id"),
                    rs.getInt("room_number"),
                    rs.getDate("check_in").toLocalDate(),
                    rs.getDate("check_out").toLocalDate(),
                    rs.getString("status"),
                    rs.getBigDecimal("amount_paid"),
                    rs.getBigDecimal("refund")
                };
                rows.add(row);
            }

            for (var row : rows) {
                long reservationId = (Long) row[0];
                int roomNumber = (Integer) row[1];
                LocalDate checkIn = (LocalDate) row[2];
                LocalDate checkOut = (LocalDate) row[3];
                String status = (String) row[4];
                BigDecimal amountPaid = (BigDecimal) row[5];
